import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"61、【中孚】 兌下巽上","description":"周易口訣義 - 61、【中孚】 兌下巽上","frontmatter":{"title":"61、【中孚】 兌下巽上","description":"周易口訣義 - 61、【中孚】 兌下巽上"},"headers":[],"relativePath":"classics/koujueyi/063.md","filePath":"classics/koujueyi/063.md"}'),r={name:"classics/koujueyi/063.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_61、【中孚】-兌下巽上" tabindex="-1">61、【中孚】 兌下巽上 <a class="header-anchor" href="#_61、【中孚】-兌下巽上" aria-label="Permalink to “61、【中孚】 兌下巽上”">​</a></h1><p>彖曰：中孚，柔在內而剛得中。說而巽，孚乃化邦也。「豚魚吉」，信及豚魚也。「利涉大川」，乘木舟虛也。中孚以「利貞」，乃應乎天也。</p><p>象曰：澤上有風，中孚。君子以議獄緩死。</p><p>初九：虞吉，有他不燕。象曰：「初九虞吉」，志未變也。</p><p>九二：鳴鶴在陰，其子和之。我有好爵，吾與爾靡之。</p><p>象曰：「其子和之」，中心願也。</p><p>六三：得敵，或鼓或罷，或泣或歌。</p><p>象曰：「或鼓或罷」，位不當也。</p><p>六四：月幾望，馬匹亡，無咎。</p><p>象曰：「馬匹亡」，絕類上也。</p><p>九五：有孚攣如，無咎。</p><p>象曰：「有孚攣如」，位正當也。</p><p>上九：翰音登於天，貞兇。</p><p>象曰：「翰音登於天」，何可長也。</p><p>無（四庫全書標明，摘錄時缺豫、隨、無妄、大壯、晉、睽、蹇、解、中孚八卦）</p>',15)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
